import * as React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Container from '@mui/material/Container';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ArrowForward from '@mui/icons-material/ArrowForward';

export default function Hero() {
  return (
    <section id="hero">
      <Box
        sx={{
          position: 'relative',
          overflow: 'hidden',
          bgcolor: 'transparent',
          minHeight: '90vh',
          display: 'flex',
          alignItems: 'center',
          backgroundImage: 'radial-gradient(circle at 50% 50%, rgba(144, 202, 249, 0.1) 0%, rgba(0, 0, 0, 0) 60%)',
        }}
      >
        <Container maxWidth="lg">
          <Stack
            spacing={4}
            sx={{
              py: { xs: 12, sm: 16 },
              maxWidth: 'md',
            }}
          >
            <Typography
              component="h1"
              variant="h1"
              sx={{
                fontSize: { xs: '2.5rem', sm: '3.5rem', md: '4rem' },
                fontWeight: 700,
                letterSpacing: '-0.02em',
                lineHeight: 1.2,
                background: 'linear-gradient(90deg, #FFFFFF 0%, rgba(255, 255, 255, 0.8) 100%)',
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
              }}
            >
              Transforming Ideas into Digital Excellence
            </Typography>

            <Typography
              variant="h4"
              component="p"
              sx={{
                color: 'text.secondary',
                fontSize: { xs: '1.125rem', sm: '1.25rem' },
                lineHeight: 1.6,
                maxWidth: '600px',
              }}
            >
              We're a design studio that helps businesses create exceptional digital products 
              and experiences. Our expertise in product design and strategy drives innovation 
              and delivers measurable results.
            </Typography>

            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              spacing={2}
              sx={{ pt: { xs: 2, sm: 4 } }}
            >
              <Button
                variant="contained"
                size="large"
                endIcon={<ArrowForward />}
                sx={{
                  py: 1.5,
                  px: 3.5,
                  fontSize: '1.125rem',
                  fontWeight: 600,
                  borderRadius: '8px',
                  textTransform: 'none',
                  background: 'linear-gradient(45deg, #90CAF9 0%, #64B5F6 100%)',
                  boxShadow: '0 8px 16px rgba(144, 202, 249, 0.2)',
                  '&:hover': {
                    background: 'linear-gradient(45deg, #64B5F6 0%, #42A5F5 100%)',
                    transform: 'translateY(-2px)',
                    boxShadow: '0 12px 20px rgba(144, 202, 249, 0.3)',
                  },
                }}
              >
                Start Your Project
              </Button>
              <Button
                variant="outlined"
                size="large"
                sx={{
                  py: 1.5,
                  px: 3.5,
                  fontSize: '1.125rem',
                  fontWeight: 600,
                  borderRadius: '8px',
                  textTransform: 'none',
                  borderWidth: '2px',
                  '&:hover': {
                    borderWidth: '2px',
                    background: 'rgba(144, 202, 249, 0.08)',
                  },
                }}
              >
                View Our Work
              </Button>
            </Stack>
          </Stack>
        </Container>

        {/* Subtle animated gradient background */}
        <Box
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: -1,
            opacity: 0.4,
            background: `
              radial-gradient(circle at 20% 30%, rgba(144, 202, 249, 0.15) 0%, transparent 40%),
              radial-gradient(circle at 80% 70%, rgba(144, 202, 249, 0.1) 0%, transparent 40%)
            `,
          }}
        />
      </Box>
    </section>
  );
}
